def render(svg_body, w, h, scale):
    doc = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" '
           f'width="{round(w * scale)}" height="{round(h * scale)}">{svg_body}</svg>')
    return Image.open(io.BytesIO(cairosvg.svg2png(bytestring=doc.encode()))).convert('RGBA')


def at(pos, body):
    return f'<g transform="translate({pos[0] - X0} {pos[1] - Y0})">{body}</g>'


def branch(piece, inside_stroke=True):
    """White shape with a 1 px dark edge. Figma strokes these inside the shape."""
    pos, d = piece
    if not inside_stroke:
        return at(pos, f'<path d="{d}" fill="white" stroke="{EDGE}"/>')
    cid = 'c%d' % (abs(hash(d)) % 10 ** 8)
    return at(pos, f'<clipPath id="{cid}"><path d="{d}"/></clipPath>'
                   f'<path d="{d}" fill="white"/>'
                   f'<path d="{d}" fill="none" stroke="{EDGE}" stroke-width="2" clip-path="url(#{cid})"/>')


GLOWS = []   # glow of the layer being built, kept apart so the mod can fade it


def with_glow(body, sigma, dy=0.0):
    """Shape; its Figma drop shadow (spread 0, opacity 1) goes to GLOWS."""
    shape = render(body, W, H, S)
    alpha = shape.getchannel('A').filter(ImageFilter.GaussianBlur(sigma * S))
    glow = Image.new('RGBA', shape.size, GLOW + (0,))
    glow.putalpha(alpha)
    if dy:
        moved = Image.new('RGBA', shape.size, (0, 0, 0, 0))
        moved.paste(glow, (0, round(dy * S)))
        glow = moved
    GLOWS.append(glow)
    return shape


# Health and stamina bars as the HUD draws them (left end cut at 45 degrees).
# The blade behind them is cut away, so the 90 % black bars stay see-through.
BAR_HOLES = [
    [(146, 997), (399.7, 997), (399.7, 1022.5), (171.5, 1022.5)],          # health "\\"
    [(171.5, 1030.1), (399.7, 1030.1), (399.7, 1055.6), (146, 1055.6)],    # stamina "/"
]


def cut_bars(im):
    from PIL import ImageDraw
    mask = Image.new('L', im.size, 0)
    d = ImageDraw.Draw(mask)
    for poly in BAR_HOLES:
        d.polygon([((x - X0) * S, (y - Y0) * S) for x, y in poly], fill=255)
    alpha = im.getchannel('A')
    alpha.paste(0, mask=mask)
    out = im.copy()
    out.putalpha(alpha)
    return out


def layer(parts):
    out = Image.new('RGBA', (W * S, H * S), (0, 0, 0, 0))
    for p in parts:
        out = Image.alpha_composite(out, p)
    return out


def plain(body):
    return render(body, W, H, S)


def front(f158, f159, ornaments):
    icons = at((146, 997), f'<path d="{PLUS}" fill="white" stroke="{EDGE}"/><path d="{BOLT}" fill="white" stroke="{EDGE}"/>')
    return layer([
        plain(branch(f158, inside_stroke=False)),
        with_glow(branch(f159), 10, dy=1),
        plain(''.join(at(p, b) for p, b in ornaments)),
        with_glow(icons, 2),
        plain(''.join(at(p, b) for p, b in LINES)),
    ])


def slot_frame():
    # 45 px rounded square, 1 px white outline (rx 7.5), rendered at 4x for a crisp sprite
    return render('<rect x="0.5" y="0.5" width="44" height="44" rx="7.5" fill="none" stroke="white"/>', 45, 45, 4)


def slot_marks():
    # Four 12.7 px wide triangles pointing out of a 45 px slot, canvas 61x61 centred on the slot.
    c, half, base, tip = 30.5, 22.5, 6.36, 6.36
    tris = []
    for dx, dy in ((0, -1), (1, 0), (0, 1), (-1, 0)):
        ex, ey = c + dx * half, c + dy * half          # middle of the slot edge
        px, py = -dy, dx                              # along the edge
        pts = [(ex + px * base, ey + py * base), (ex - px * base, ey - py * base), (ex + dx * tip, ey + dy * tip)]
        tris.append('<path d="M%.2f %.2fL%.2f %.2fL%.2f %.2fZ" fill="white"/>' % sum(pts, ()))
    return render(''.join(tris), 61, 61, 4)


def main():
    os.makedirs(OUT, exist_ok=True)
    outputs = {}
    # Every layer comes with a <name>_glow.png: the HUD draws it under the layer
    # with the opacity of [Yggdrasil] GlowStrength.
    for name, build in (('ygg_back', lambda: with_glow(branch(BACK4), 5)),
                        ('ygg_back3', lambda: with_glow(branch(BACK3), 5)),
                        ('ygg_front', lambda: front(FRAME158_4, FRAME159_4, ORNAMENTS_4)),
                        ('ygg_front3', lambda: front(FRAME158_3, FRAME159_3, ORNAMENTS_3))):
        GLOWS.clear()
        outputs[name] = build()
        outputs[name + '_glow'] = layer(GLOWS)
        if name.startswith('ygg_back'):
            outputs[name] = cut_bars(outputs[name])
            outputs[name + '_glow'] = cut_bars(outputs[name + '_glow'])
    outputs.update({
        'ygg_slot': slot_frame(),
        'ygg_slot_marks': slot_marks(),
        'ygg_ammo': render(f'<path d="{ARROW}" fill="white"/>', 32, 5, 4),
        'ygg_ammo_tip': render(f'<path d="{ARROW_TIP}" fill="white"/>', 32, 5, 4),
    })
    for name, im in outputs.items():
        im.save(os.path.join(OUT, name + '.png'), optimize=True)
        print(name, im.size)


if __name__ == '__main__':
    main()
